using System.ComponentModel.DataAnnotations;

namespace SocialMediaWeb.Dtos;

public sealed class SendChatMessageDto
{
    [Range(1, int.MaxValue)]
    public int ReceiverId { get; init; }

    [Required]
    [StringLength(2000)]
    public string Content { get; init; } = string.Empty;

    /// <summary>
    /// Optional id generated by the client. Reusing it on a retry makes delivery idempotent.
    /// </summary>
    public Guid? ClientMessageId { get; init; }
}
